typedef unsigned char uint8;
typedef unsigned int uint32;

class color32
{
public:
  union
  {
    struct { uint8 b, g, r, a; } c;
    uint32 i;
  };

  color32(uint8 r, uint8 g, uint8 b, uint8 a = 255)
  {
    c.b = b;
    c.g = g;
    c.r = r;
    c.a = a;
  }

  uint8 get_red() const { return c.r; }
  uint8 get_green() const { return c.g; }
  uint8 get_blue() const { return c.b; }
};

class os_developer_options
{
  int values[189];

public:
  static os_developer_options *inst();
  int get_int(int index) const { return values[index]; }
};

extern os_developer_options *developer_options_instance;
__asm__(".equ developer_options_instance, 0x0046B180");
inline os_developer_options *os_developer_options::inst()
{
  return developer_options_instance;
}

struct TextString
{
  char padding[72];
  color32 color;
};

extern "C" void igo_update(void *, float) __asm__("Update__9IGOWidgetf");
extern "C" float sinf(float);

class ReplayWidget
{
  char padding[88];
  TextString *pauseText;
  char padding2[4];
  float highlight_intensity;
  float highlight_timer;

public:
  void Update(float dt);
};

void ReplayWidget::Update(const float dt)
{
  igo_update(this, dt);

  float period =
    (float)(os_developer_options::inst()->get_int(188)) /
    1000.0f;

  highlight_timer += dt;
  highlight_intensity = 0.5f * sinf(2 * 3.14159265358979323846f *
                                     (highlight_timer / period));

  static color32 c = color32(224, 128, 0, 255);
  static color32 ch = color32(255, 255, 0, 255);

  int r = (int)(c.get_red() + (highlight_intensity + .5f) *
                (ch.get_red() - c.get_red()));
  int g = (int)(c.get_green() + (highlight_intensity + .5f) *
                (ch.get_green() - c.get_green()));
  int b = (int)(c.get_blue() + (highlight_intensity + .5f) *
                (ch.get_blue() - c.get_blue()));
  int a = 255;

  pauseText->color = color32(r, g, b, a);
}
